frappe.ui.form.on('Purchase Order', {
    refresh: function(frm) {
        var company = frm.doc.company;

        frappe.call({
            method: 'frappe.client.get_list',
            args: {
                doctype: 'Account',
                filters: { company: company, account_name: ['like', "Stock Received But Not Billed"] },
                limit: 1
            },
            callback: function(response) {
                if (response.message && response.message.length > 0) {
                    frm.set_query('custom_expense_account', function() {
                        return {
                            filters: {
                                company: company,
                                account_name: ['like', "Stock Received But Not Billed"]
                            }
                        };
                    });
                    var firstAccount = response.message[0];
                    frm.set_value('custom_expense_account', firstAccount.name);
                    frm.refresh_field('custom_expense_account');

                    // Set expense_account in child table
                    frm.doc.items.forEach(function(item) {
                        frappe.model.set_value(item.doctype, item.name, 'expense_account', firstAccount.name);
                    });
                    frm.refresh_field('items');
                }
            }
        });
    }
});

// On item selection, set cost_center for that specific row
frappe.ui.form.on('Purchase Receipt Item', {
    item_code: function (frm, cdt, cdn) {
        setCostcenterForRow(frm, cdt, cdn);
    }
});

// On form refresh, set cost_center for all rows
frappe.ui.form.on('Purchase Receipt', {
    refresh: function (frm) {
        setCostcenterForAll(frm);
    }
});

// Set cost_center for a single row
function setCostcenterForRow(frm, cdt, cdn) {
    let row = locals[cdt][cdn];
    let station = frm.doc.cost_center;

    if (station) {
        frappe.model.set_value(cdt, cdn, 'cost_center', station);
        frm.refresh_field('items');
    } else {
        frappe.msgprint("Please set the Cost Center first.");
    }
}

// Set cost_center for all rows
function setCostcenterForAll(frm) {
    let station = frm.doc.cost_center;

    if (station && frm.doc.items) {
        frm.doc.items.forEach(function (item) {
            item.cost_center = station;
        });
        frm.refresh_field('items');
    }
}

frappe.ui.form.on('Sales Invoice', {
  loyalty_points: function(frm) {
    if (!frm.doc.customer) return;

    // Call to fetch earned points and loyalty program details for the customer
    frappe.call({
      method: "frappe.client.get_list",
      args: {
        doctype: "Loyalty Point Entry",
        filters: {
          customer: frm.doc.customer,
          expiry_date: [">=", frappe.datetime.get_today()]
        },
        fields: ["loyalty_points", "loyalty_program"]
      },
      callback: function(r) {
        let earned = 0;
        let redeemed = frm.doc.loyalty_points || 0; // Get redeemed points from Sales Invoice
        let program = null;

        // Sum up all earned points
        (r.message || []).forEach(entry => {
          if (entry.loyalty_points > 0) {
            earned += entry.loyalty_points;
          }

          if (!program && entry.loyalty_program) {
            program = entry.loyalty_program;
          }
        });

        // Calculate remaining points
        let remaining = earned - redeemed;

        // If loyalty program exists and remaining points are more than 0
        if (program && remaining > 0) {
          frappe.call({
            method: "frappe.client.get",
            args: {
              doctype: "Loyalty Program",
              name: program
            },
            callback: function(p) {
              let conversion_rate = p.message?.conversion_factor || 0;

              // Calculate the total value of redeemed points
              let redeemed_value = redeemed * conversion_rate;

              let msg = `
                <b>Loyalty Summary for ${frm.doc.customer}:</b><br>
                ✅ Total Earned Points: <b>${earned}</b><br>
                ❌ Total Redeemed Points: <b>${redeemed}</b><br>
                🏁 Remaining Points: <b>${remaining}</b><br>
                💰 Value of Redeemed Points: <b>${frappe.format(redeemed_value, {fieldtype: 'Currency'})}</b><br>
                💰 Value of Remaining Points: <b>${frappe.format(remaining * conversion_rate, {fieldtype: 'Currency'})}</b>
              `;
              frappe.msgprint(msg);
            }
          });
        } else {
          let msg = `
            <b>Loyalty Summary for ${frm.doc.customer}:</b><br>
            ✅ Total Earned Points: <b>${earned}</b><br>
            ❌ Total Redeemed Points: <b>${redeemed}</b><br>
            🏁 Remaining Points: <b>${remaining}</b><br>
            💰 Value of Redeemed Points: <b>${frappe.format(0, {fieldtype: 'Currency'})}</b><br>
            ⚠️ No Loyalty Program found.
          `;
          frappe.msgprint(msg);
        }
      }
    });
  }
});

frappe.ui.form.on('Request for Quotation Item', {
    item_code: function (frm, cdt, cdn) {
        let row = locals[cdt][cdn];
        if (!row.item_code) return;

        const existing_suppliers = frm.doc.suppliers.map(s => s.supplier);

        frappe.call({
            method: "gormsolutions_mobile_app.api.rfq.get_item_suppliers_with_email",
            args: {
                item_code: row.item_code,
                existing_suppliers: existing_suppliers
            },
            callback: function (r) {
                if (!r.message) return;

                r.message.forEach(supplier => {
                    frm.add_child("suppliers", {
                        supplier: supplier.supplier,
                        email_id: supplier.email_id
                    });
                });
                frm.refresh_field("suppliers");
            }
        });
    }
});

frappe.ui.form.on('Repost Item Valuation', {
    refresh(frm) {
        if (frm.doc.docstatus === 1) {  // Only show button on submitted docs
            frm.add_custom_button('Force Cancel', () => {
                frappe.call({
                    method: "your_app.api.repost.force_cancel_repost",
                    args: {
                        docname: frm.doc.name
                    },
                    callback: function(r) {
                        if(r.message) {
                            frappe.msgprint(r.message);
                            frm.reload_doc();
                        }
                    }
                });
            }, 'Actions');
        }
    }
});

// Parent Doctype: Batch Work Order
frappe.ui.form.on('Batch Work Order', {
    refresh(frm) {
        if (
            frm.doc.docstatus === 1 &&
            frm.doc.status === 'Awaiting FG Transfer'
        ) {
            frm.add_custom_button('Transfer Additional Items', () => {
                frappe.call({
                    method: 'gormsolutions_mobile_app.custom_api.stock.batch_work_order.create_stock_transfer',
                    args: { docname: frm.doc.name },
                    callback(r) {
                        if (r.message) {
                            frappe.msgprint(__('Stock Entry {0} created', [r.message]));
                            frappe.set_route("Form", "Stock Entry", r.message);
                        }
                    }
                });
            }, 'Actions');
        }
    }
});

// Child Table: Batch Work Order Required Item
frappe.ui.form.on('Batch Work Order Required Item', {
    required_qty(frm, cdt, cdn) {
        const row = locals[cdt][cdn];
        if (row.additional === 1 && row.required_qty) {
            row.transferred_qty = row.required_qty;
            row.consumed_qty = row.required_qty;
            frm.refresh_field('required_items');
        }
    },
    additional(frm, cdt, cdn) {
        const row = locals[cdt][cdn];
        if (row.additional === 1 && row.required_qty) {
            row.transferred_qty = row.required_qty;
            row.consumed_qty = row.required_qty;
            frm.refresh_field('required_items');
        }
    }
});

frappe.ui.form.on('Request for Quotation Item', {
    item_code: function (frm, cdt, cdn) {
        let row = locals[cdt][cdn];
        if (!row.item_code) return;

        const existing_suppliers = frm.doc.suppliers.map(s => s.supplier);

        frappe.call({
            method: "gormsolutions_mobile_app.custom_api.quotations.requst_quotation.get_item_suppliers_with_email",
            args: {
                item_code: row.item_code,
                existing_suppliers: existing_suppliers
            },
            callback: function (r) {
                // console.log(r)
                if (!r.message) return;

                r.message.forEach(supplier => {
                    frm.add_child("suppliers", {
                        supplier: supplier.supplier,
                        email_id: supplier.email_id,
                        custom_mobile_no: supplier.mobile_no
                    });
                });
                frm.refresh_field("suppliers");
            }
        });
    }
});
